"use client";

import React from "react";
import { AlertTriangle } from "lucide-react";
import { cn } from "@/lib/utils";
import { HoldButton } from "./hold-button";
import { GridButton } from "./grid-button";
import { ShinyButton } from "./shiny-button";
import { CooldownButton } from "./cooldown-button";
import { HoldConfirmButton } from "./hold-confirm-button";
import { DontPressButton } from "./dont-press-button";
import { ConfettiButton } from "./confetti-button";
import { PillButton } from "./pill-button";
import { MorphStatusButton } from "./morph-status-button";
import { CopyButton } from "./copy-button";

export function EvilButtonsGroup({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      data-slot="evil-buttons-group"
      className={cn(
        "mx-auto flex w-full max-w-3xl flex-col gap-6 rounded-3xl bg-zinc-950 p-8 text-white shadow-2xl border border-zinc-800/80 font-sans select-none",
        className
      )}
      {...props}
    >
      <div className="flex flex-col gap-1 border-b border-zinc-800/80 pb-4">
        <h3 className="text-xl font-bold tracking-tight text-white flex items-center gap-2">
          <AlertTriangle className="h-5 w-5 text-amber-400" />
          Evil Buttons Collection
        </h3>
        <p className="text-xs text-zinc-400">
          A suite of 10 interactive button micro-interactions built with Framer Motion, spring physics, and Apple UI design.
        </p>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4 items-center justify-items-center">
        <HoldButton />
        <GridButton />
        <ShinyButton />
        <CooldownButton />
        <HoldConfirmButton />
        <DontPressButton />
        <ConfettiButton />
        <PillButton />
        <MorphStatusButton />
        <CopyButton />
      </div>
    </div>
  );
}

export default EvilButtonsGroup;
